            assert_eq!(member.to_string().parse::<Auspiciousness>(), Ok(member));
            let json = serde_json::to_string(&member).unwrap();
            assert_eq!(serde_json::from_str::<Auspiciousness>(&json).unwrap(), member);
            assert_eq!(<Auspiciousness as Catalogued>::mark(member), member.mark());
            assert_ne!(member.doc(), "");
